// Hidden test for TRK-DEV-1 (fiks dev DriftPackage; hidden): list_comments still reads the v1 response format
// Manifestation: v1 behaviour preserved (vendor v1 without the drift)
// Generated by fiks packages/vendor-tracker/src/build-trk-dev-1.ts: upstream responses recorded from
// tracker vendor v1 under the frozen clock; expected outputs from
// v1 ground truth. Self-contained: copy into <tracker-mcp>/test/hidden/ and run with vitest.
import { createServer } from 'node:http';
import type { AddressInfo } from 'node:net';
import type { CallToolResult } from '@modelcontextprotocol/sdk/types.js';
import { expect, test } from 'vitest';
import * as tools from '../../src/tools/handlers.ts';
import { createVendorClient } from '../../src/vendor.ts';

interface Exchange {
  method: string;
  path: string;
  status: number;
  headers: Record<string, string>;
  body: string;
}

interface Step {
  tool: string;
  args: Record<string, unknown>;
  expected: unknown;
}

const UPSTREAM: Exchange[] = [
  {
    "method": "GET",
    "path": "/issues/TRK-104/comments",
    "status": 200,
    "headers": {
      "content-type": "application/json",
      "tracker-api-version": "2026-01-01"
    },
    "body": "{\"issue_key\":\"TRK-104\",\"items\":[{\"id\":\"cm-6\",\"issue_key\":\"TRK-104\",\"author\":\"frank\",\"body\":\"Archived projects vanished from search after the index rebuild.\",\"created_at\":\"2026-07-11T15:50:00.000Z\"},{\"id\":\"cm-7\",\"issue_key\":\"TRK-104\",\"author\":\"dan\",\"body\":\"Root cause: the archive flag was indexed as a string.\",\"created_at\":\"2026-08-29T09:12:00.000Z\"},{\"id\":\"cm-8\",\"issue_key\":\"TRK-104\",\"author\":\"dan\",\"body\":\"Fixed in the nightly; please verify.\",\"created_at\":\"2026-09-02T12:00:00.000Z\"},{\"id\":\"cm-9\",\"issue_key\":\"TRK-104\",\"author\":\"frank\",\"body\":\"Verified on staging.\",\"created_at\":\"2026-09-02T14:30:00.000Z\"}],\"total\":4}"
  }
];

const STEPS: Step[] = [
  {
    "tool": "list_comments",
    "args": {
      "issue_key": "TRK-104"
    },
    "expected": {
      "issue_key": "TRK-104",
      "items": [
        {
          "id": "cm-6",
          "author": "frank",
          "body": "Archived projects vanished from search after the index rebuild.",
          "created_at": "2026-07-11T15:50:00.000Z"
        },
        {
          "id": "cm-7",
          "author": "dan",
          "body": "Root cause: the archive flag was indexed as a string.",
          "created_at": "2026-08-29T09:12:00.000Z"
        },
        {
          "id": "cm-8",
          "author": "dan",
          "body": "Fixed in the nightly; please verify.",
          "created_at": "2026-09-02T12:00:00.000Z"
        },
        {
          "id": "cm-9",
          "author": "frank",
          "body": "Verified on staging.",
          "created_at": "2026-09-02T14:30:00.000Z"
        }
      ],
      "count": 4,
      "total": 4
    }
  }
];

type Tool = { name: string; handler(args: never, vendor: ReturnType<typeof createVendorClient>): Promise<CallToolResult> };
const TOOLS = new Map((Object.values(tools) as unknown as Tool[]).map((t) => [t.name, t]));

/** Serves each recorded response once, matched by method and path (query and headers ignored). */
async function serve(exchanges: Exchange[]) {
  const pending = [...exchanges];
  const unmatched: string[] = [];
  const server = createServer((req, res) => {
    req.resume();
    req.on('end', () => {
      const path = new URL(req.url ?? '/', 'http://upstream.local').pathname;
      const i = pending.findIndex((e) => e.method === req.method && e.path === path);
      if (i === -1) {
        unmatched.push(`${req.method} ${req.url}`);
        res.writeHead(599, { 'content-type': 'application/json' });
        res.end(JSON.stringify({ error: 'UNMATCHED_REQUEST' }));
        return;
      }
      const [e] = pending.splice(i, 1) as [Exchange];
      res.writeHead(e.status, e.headers);
      res.end(e.body);
    });
  });
  await new Promise<void>((r) => server.listen(0, '127.0.0.1', r));
  const url = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  const close = () =>
    new Promise<void>((r) => {
      server.closeAllConnections();
      server.close(() => r());
    });
  return { url, unmatched, close };
}

test('[TRK-DEV-1 hidden] list_comments still reads the v1 response format', async () => {
  const upstream = await serve(UPSTREAM);
  try {
    const vendor = createVendorClient(upstream.url);
    for (const step of STEPS) {
      const tool = TOOLS.get(step.tool);
      if (!tool) throw new Error(`unknown tool ${step.tool}`);
      const result = await tool.handler(step.args as never, vendor);
      const text = (result.content as { text?: string }[] | undefined)?.map((x) => x.text).join(' ');
      expect(result.isError, `${step.tool} returned an error: ${text}`).toBeFalsy();
      expect(result.structuredContent, `${step.tool}(${JSON.stringify(step.args)})`).toEqual(step.expected);
    }
    expect(upstream.unmatched, 'requests the recorded upstream never answered').toEqual([]);
  } finally {
    await upstream.close();
  }
});
